1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: Damage[];
19	};
20	
21	/**
22	 * One type covers both ops, so items/policy/incident are all optional. A
23	 * discriminated union on `op` would express this better, but the spec's
24	 * scenarios are plain object literals whose `op` widens to `string` and so
25	 * would no longer typecheck against literal `"quote"` / `"claim"` variants.
26	 * Revisit if a scenario parser ever narrows `op` on the way in.
27	 */
28	export type Step = {
29	  op: string;
30	  items?: Item[];
31	  policy?: number;
32	  incident?: Incident;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = { premium: number };
41	export type ClaimResult = { payout: number; remainingCap: number };
42	
43	export type ScenarioResult = {
44	  results: (QuoteResult | ClaimResult)[];
45	};
46	
47	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	};
55	/**
56	 * Deliberately NOT derived from the base premiums, though every entry today
57	 * happens to be 10x its counterpart. The MHPCO publishes two independent
58	 * price lists ("Sword: 1000 G insurance value, 100 G base premium"), and the
59	 * rules already pull them apart: the 3-alike building block cuts the base
60	 * premium to 60 G while the insurance value stays 250 G per component. Making
61	 * one a function of the other would encode a coincidence as a rule.
62	 */
63	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
64	  sword: 1000,
65	  amulet: 600,
66	  staff: 800,
67	  potion: 400,
68	  rune: 250,
69	  moonstone: 250,
70	};
71	const DEDUCTIBLE = 100;
72	const CAP_MULTIPLE = 2;
73	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
74	const CURSE_SURCHARGE_PERCENT = 50;
75	const HIGH_ENCHANTMENT_THRESHOLD = 5;
76	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
77	const LOYALTY_THRESHOLD_YEARS = 2;
78	const LOYALTY_DISCOUNT_PERCENT = 20;
79	const FOLLOWUP_DISCOUNT_PERCENT = 15;
80	const PROCESSING_FEE = 5;
81	
82	const percentOf = (amount: number, percent: number): number =>
83	  (amount * percent) / 100;
84	
85	/**
86	 * Premiums round UP — the MHPCO's favour on money coming IN. Payouts will need
87	 * the opposite direction, so this deliberately names the premium case only
88	 * rather than a general "in the MHPCO's favour" rounding.
89	 */
90	const roundPremiumUp = (premium: number): number => Math.ceil(premium);
91	
92	const BLOCK_SIZE = 3;
93	const BLOCK_BASE_PREMIUM = 60;
94	
95	/** Counts of items of the same type — "alike" in the MHPCO's terms. */
96	const countAlikeItems = (items: Item[]): Map<string, number> =>
97	  items.reduce(
98	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
99	    new Map<string, number>(),
100	  );
101	
102	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
103	
104	const basePremiumForAlikeItems = (type: string, count: number): number =>
105	  formsBuildingBlock(count)
106	    ? BLOCK_BASE_PREMIUM
107	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
108	
109	const policyBasePremium = (items: Item[]): number =>
110	  [...countAlikeItems(items)].reduce(
111	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
112	    0,
113	  );
114	
115	const itemBasePremium = (item: Item): number =>
116	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
117	
118	const isHighlyEnchanted = (item: Item): boolean =>
119	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
120	
121	/** Item-specific surcharges stack additively. */
122	const itemSurchargePercent = (item: Item): number =>
123	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
124	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
125	
126	/**
127	 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
128	 * premium — unlike policy-wide modifiers, which apply to the policy base.
129	 */
130	const totalItemSurcharges = (items: Item[]): number =>
131	  items.reduce(
132	    (total, item) =>
133	      total + percentOf(itemBasePremium(item), itemSurchargePercent(item)),
134	    0,
135	  );
136	
137	const isLongStanding = (customer: Customer): boolean =>
138	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
139	
140	/**
141	 * The net of all policy-wide percentages. Policy-wide modifiers are
142	 * percentages of the POLICY base premium — unlike item-specific modifiers,
143	 * which apply to the affected item's own base. The net is negative when the
144	 * discounts outweigh the surcharges: a long-standing customer nets -10 %.
145	 */
146	const netPolicyAdjustmentPercent = (
147	  customer: Customer,
148	  precedingSteps: number,
149	): number =>
150	  FIRST_INSURANCE_SURCHARGE_PERCENT -
151	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_PERCENT : 0) -
152	  // The follow-up discount is owed on every quote after the customer's FIRST
153	  // QUOTE, but what we have here is a count of preceding STEPS. The two
154	  // coincide only because every step exercised so far is a quote; once claim
155	  // steps arrive, [quote, claim, quote] will wrongly discount the third step
156	  // as a second follow-up. No test forces the distinction yet.
157	  (precedingSteps > 0 ? FOLLOWUP_DISCOUNT_PERCENT : 0);
158	
159	const policyAdjustment = (
160	  policyBase: number,
161	  customer: Customer,
162	  precedingSteps: number,
163	): number =>
164	  percentOf(policyBase, netPolicyAdjustmentPercent(customer, precedingSteps));
165	
166	const quotePremium = (
167	  items: Item[],
168	  customer: Customer,
169	  precedingSteps: number,
170	): number => {
171	  const basePremium = policyBasePremium(items);
172	  return roundPremiumUp(
173	    basePremium +
174	      totalItemSurcharges(items) +
175	      policyAdjustment(basePremium, customer, precedingSteps) +
176	      PROCESSING_FEE,
177	  );
178	};
179	
180	const roundPayoutDown = (payout: number): number => Math.floor(payout);
181	
182	const insuranceSum = (items: Item[]): number =>
183	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_ITEM_TYPE[item.type], 0);
184	
185	/** The deductible applies once per damaged item, not once per incident. */
186	const payoutFor = (incident: Incident): number =>
187	  incident.damages.reduce(
188	    (total, damage) => total + damage.amount - DEDUCTIBLE,
189	    0,
190	  );
191	
192	/** A claim's `policy` field is the index of the quote step that wrote it. */
193	const itemsCoveredBy = (policy: number, scenario: Scenario): Item[] =>
194	  scenario.steps[policy].items ?? [];
195	
196	/** The MHPCO caps a policy at twice its insurance sum. */
197	const capFor = (policyItems: Item[]): number =>
198	  CAP_MULTIPLE * insuranceSum(policyItems);
199	
200	const claimResult = (step: Step, scenario: Scenario): ClaimResult => {
201	  const cap = capFor(itemsCoveredBy(step.policy ?? 0, scenario));
202	  // Non-null: runScenario only routes here when op === "claim", and every
203	  // claim step carries an incident. See the Step doc comment.
204	  const payout = roundPayoutDown(payoutFor(step.incident!));
205	  return { payout, remainingCap: cap - payout };
206	};
207	
208	export const runScenario = (scenario: Scenario): ScenarioResult => ({
209	  results: scenario.steps.map((step, precedingSteps) =>
210	    step.op === "claim"
211	      ? claimResult(step, scenario)
212	      : {
213	          premium: quotePremium(
214	            step.items ?? [],
215	            scenario.customer,
216	            precedingSteps,
217	          ),
218	        },
219	  ),
220	});
